import{_ as t}from"./chunks/mob2-report-form.79df2add.js";import{_ as e,o,c as i,Q as a}from"./chunks/framework.b67c47e6.js";const b=JSON.parse('{"title":"MOB v2 Machine File","description":"","frontmatter":{},"headers":[],"relativePath":"guide/machine_files/formats/panel_mob2/index.md","filePath":"guide/machine_files/formats/panel_mob2/index.md","lastUpdated":1790346505000}'),r={name:"guide/machine_files/formats/panel_mob2/index.md"},n=a('<h1 id="mob-v2-machine-file" tabindex="-1">MOB v2 Machine File <a class="header-anchor" href="#mob-v2-machine-file" aria-label="Permalink to &quot;MOB v2 Machine File&quot;">​</a></h1><p>The MOB v2 is an advanced panel assembly file format for the H&amp;M Mobi One V2, Frame Station V2, Robobrick and Isolation machines. It extends MOB v1 with support for several tool carriages, flooring stations, and more granular tool control.</p><p><img src="'+t+'" alt="The report form for a MOB v2 file"></p><ol><li><strong>MOB v2 panel file</strong> as the report type.</li><li>The document status.</li><li>One <strong>Station Job Options</strong> block per station with a machine, holding the options of this page.</li><li>The production line the file is made for.</li><li>The assemblies to include.</li><li><strong>Submit</strong>.</li></ol><nav class="table-of-contents"><ul><li><a href="#output">Output</a></li><li><a href="#parameters">Parameters</a><ul><li><a href="#general">General</a></li><li><a href="#framing">Framing</a></li><li><a href="#cladding-options">Cladding Options</a></li><li><a href="#mill-directions">Mill Directions</a></li><li><a href="#saw-directions">Saw Directions</a></li><li><a href="#tool-assignments">Tool Assignments</a></li><li><a href="#robobrick-specific">Robobrick-Specific</a></li><li><a href="#isolation-specific">Isolation-Specific</a></li></ul></li></ul></nav><h2 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h2><ul><li><strong>Format:</strong> ZIP containing one <code>.mob2</code> file per panel, named <code>&lt;panel&gt;_rev&lt;revision&gt;.mob2</code> and sorted in folders by phase and batch</li><li><strong>Target machines:</strong> Mobi One V2, Frame Station V2, Robobrick, Isolation Machine</li><li><strong>Requires:</strong> A production line whose stations have one of these machines. The report form shows one <strong>Station Job Options</strong> block per station with a machine.</li></ul><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h2><p>These are the options of a Mobi One V2 station. The labels are the ones shown in the report form.</p><h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><table><thead><tr><th>Parameter</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><strong>Production starting side</strong> (walls / floors)</td><td>Machine zero mode: &#39;walls&#39; or &#39;floors&#39;. This field and the next one carry the same label in the form.</td><td>walls</td></tr><tr><td><strong>Production starting side</strong> (inside / outside)</td><td>Begin processing from the &#39;inside&#39; or &#39;outside&#39; face.</td><td>inside</td></tr><tr><td><strong>Shift mode</strong></td><td>How operations shift between layers: &#39;No shift&#39;, &#39;Shift on layers&#39;, &#39;Shift on operations&#39;.</td><td>Shift on operations</td></tr><tr><td><strong>File generation with operations that exceeds the machine sizes</strong></td><td>Handling oversized operations: &#39;Trim operations up to max size&#39;, &#39;Do not generate the layer&#39;, or &#39;Generate it anyway&#39;.</td><td>Generate it anyway</td></tr></tbody></table><h3 id="framing" tabindex="-1">Framing <a class="header-anchor" href="#framing" aria-label="Permalink to &quot;Framing&quot;">​</a></h3><table><thead><tr><th>Parameter</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><strong>Use Custom Matrix pattern</strong></td><td>Use the custom framing nail matrix of the machine setup instead of the automatic one.</td><td>Off</td></tr></tbody></table><h3 id="cladding-options" tabindex="-1">Cladding Options <a class="header-anchor" href="#cladding-options" aria-label="Permalink to &quot;Cladding Options&quot;">​</a></h3><table><thead><tr><th>Parameter</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><strong>Plates nailing pattern</strong></td><td>&#39;Regular pattern&#39;, &#39;Large panel pattern&#39;, or &#39;Single Nailing Optimized (BETA)&#39;.</td><td>Regular pattern</td></tr><tr><td><strong>Minimum panel height for twin nailing</strong></td><td>Panels shorter than this height (mm) always use single nailing, even when a twin nailer is configured. 0 disables the limit.</td><td>0</td></tr></tbody></table><h3 id="mill-directions" tabindex="-1">Mill Directions <a class="header-anchor" href="#mill-directions" aria-label="Permalink to &quot;Mill Directions&quot;">​</a></h3><p>Section <strong>Milling Mill directions</strong>.</p><table><thead><tr><th>Parameter</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><strong>Inside Contour</strong></td><td>Mill direction for the contour on the inside face.</td><td>Counter Clockwise</td></tr><tr><td><strong>Outside Contour</strong></td><td>Mill direction for the contour on the outside face.</td><td>Clockwise</td></tr><tr><td><strong>Inside Holes</strong></td><td>Mill direction for holes on the inside face.</td><td>Clockwise</td></tr><tr><td><strong>Outside Holes</strong></td><td>Mill direction for holes on the outside face.</td><td>Counter Clockwise</td></tr></tbody></table><h3 id="saw-directions" tabindex="-1">Saw Directions <a class="header-anchor" href="#saw-directions" aria-label="Permalink to &quot;Saw Directions&quot;">​</a></h3><p>Section <strong>Sawing Saw directions</strong>. The same four settings for sawing: <strong>Inside Contour (Saw)</strong>, <strong>Outside Contour (Saw)</strong>, <strong>Inside Holes (Saw)</strong> and <strong>Outside Holes (Saw)</strong>. When a saw direction is not set, the matching mill direction is used.</p><h3 id="tool-assignments" tabindex="-1">Tool Assignments <a class="header-anchor" href="#tool-assignments" aria-label="Permalink to &quot;Tool Assignments&quot;">​</a></h3><p>Sections <strong>Cladding Tool IDs</strong> and <strong>Processing Tool IDs</strong>. Each field only offers the tools that the machine configuration file declares as present.</p><table><thead><tr><th>Tool type</th><th>Fields</th><th>Tool IDs offered</th><th>Default ID</th></tr></thead><tbody><tr><td><strong>Cladding nailer</strong></td><td>Plates Nailer Tool ID zone 1–3 Inside / Outside</td><td>24, 25, 26, 44, 45, 46, 24+44, 25+45, 26+46, Single nailing from model, Twin nailing from model</td><td>5</td></tr><tr><td><strong>Cladding screwer</strong></td><td>Screwdriver Tool ID zone 1–3 Inside / Outside</td><td>0, 1</td><td>0 (disabled)</td></tr><tr><td><strong>Batten nailer</strong></td><td>Battens Tool ID zone Inside / Outside</td><td>24, 25, 26, 44, 45, 46</td><td>25</td></tr><tr><td><strong>Mill tool</strong></td><td>Milling tool id</td><td>28, 48</td><td>28</td></tr><tr><td><strong>Saw tool</strong></td><td>Sawing tool id</td><td>23, 33, 43</td><td>23</td></tr><tr><td><strong>Drill tool</strong></td><td>Drilling tool id</td><td>22, 42</td><td>22</td></tr><tr><td><strong>Glue tool</strong></td><td>Gluing tool id</td><td>29, 49, 29+49</td><td>29</td></tr></tbody></table><h3 id="robobrick-specific" tabindex="-1">Robobrick-Specific <a class="header-anchor" href="#robobrick-specific" aria-label="Permalink to &quot;Robobrick-Specific&quot;">​</a></h3><table><thead><tr><th>Parameter</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><strong>Use Opimized mode</strong></td><td>Use optimized brick placement sequencing.</td><td>On</td></tr><tr><td><strong>Max distance between Glue lines for joining them</strong></td><td>Maximum distance (mm) to join adjacent glue lines.</td><td>100</td></tr><tr><td><strong>UUID Export mode</strong></td><td>&#39;IFC GID (base64) (produuz.it standard)&#39; or &#39;IFC GID converted to canonical UUID v4&#39;.</td><td>IFC GID (base64)</td></tr></tbody></table><h3 id="isolation-specific" tabindex="-1">Isolation-Specific <a class="header-anchor" href="#isolation-specific" aria-label="Permalink to &quot;Isolation-Specific&quot;">​</a></h3><p>The Isolation Machine form has the two <strong>Production starting side</strong> fields, <strong>Shift mode</strong>, and:</p><table><thead><tr><th>Parameter</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><strong>Export Isolation as CSV</strong></td><td>Also export the isolation data as a CSV file, added to the ZIP next to the <code>.mob2</code> file.</td><td>Off</td></tr></tbody></table>',28),s=[n];function d(l,h,c,g,m,f){return o(),i("div",null,s)}const w=e(r,[["render",d]]);export{b as __pageData,w as default};
